const items = $input.all();
const validTweets = [];

for (const item of items) {
  const tweet = item.json;

  // Lewati jika ini adalah mock data
  if (tweet.id === -1 || tweet.id === "-1" || (tweet.text && tweet.text.includes("KaitoEasyAPI"))) {
    continue;
  }

  if (tweet.text) {
    const rawUrl = tweet.twitterUrl || tweet.url || '';
    const extractedId = tweet.id || rawUrl.split('/').pop() || Math.random().toString();

    // Ekstrak username dari URL (format: https://twitter.com/username/status/...)
    let username = 'unknown';
    if (rawUrl.includes('/status/')) {
      username = rawUrl.split('/status/')[0].split('/').pop();
    }

    validTweets.push({
      json: {
        tweet_id: extractedId.toString(),
        text: tweet.text,
        author_username: username,
        tweet_url: rawUrl,
        created_at: tweet.createdAt || new Date().toISOString(),
        likes: tweet.likeCount || 0,
        retweets: tweet.retweetCount || 0,
        crawled_at: new Date().toISOString()
      }
    });
  }
}

return validTweets;
